declare const tools: { mcp__lens_studio__CaptureRuntimeViewTool(args: {
  // World-space point to look at when `uniqueIds` is empty. Defaults to (0,0,0). Ignored when `uniqueIds` is provided.
  center?: { x?: number; y?: number; z?: number; };
  // Image resolution preset. 'low' (256x192) for quick checks, 'medium' (512x384, default) for general verification, 'high' (1024x768) for fine details and text readability.
  detail?: "low" | "medium" | "high";
  // Extra space around the region. In object mode this is bbox padding (cm) — `distance / 2` is added to each half-extent; omit for tight framing. In scene mode this is the full size of the cube around `center` (default 100 → ±50 view extent). Smaller values zoom in.
  distance?: number;
  // Hide every scene object not in `uniqueIds`. Useful when other objects occlude the targets. Ignored in scene mode.
  isolate?: boolean;
  // Preview panel label (e.g. 'Preview 1', 'Player 1', 'Wearable Experience'). On first use, lazily binds to the next available preview panel by panel title; subsequent calls with the same label route to the same panel. Omit to broadcast to all open preview panels.
  previewName?: string;
  // Maximum ms to wait for the lens to respond. Defaults to 5000.
  timeoutMs?: number;
  // Scene objects to frame. When non-empty, switches to object mode — the camera auto-frames the combined bounding box. Use a single-element array for one object. Discover uniqueIds via QueryRuntimeSceneTool.
  uniqueIds?: Array<string>;
  // Camera perspective. Relative to the object's rotation when targeting a single uniqueId; world-aligned in scene mode and for multi-object framing. Defaults to 'isometric'.
  viewAngle?: "isometric" | "top" | "front" | "back" | "left" | "right";
}): Promise<CallToolResult>; };
