declare const tools: { mcp__lens_studio__RunAndCollectLogsTool(args: {
  // 'refresh' (default) refreshes the preview and captures post-reset logs — use for verifying after code changes. 'tail' reads the existing log's last `tailBytes` without resetting — use for diagnosing user-reported issues without wiping evidence.
  mode?: "refresh" | "tail";
  // refresh mode only: hard cap on the settle window. Worst-case tool wall time is roughly timeoutMs + settleMaxMs; raise both together for long-onAwake Lenses but keep the sum below your MCP transport timeout.
  settleMaxMs?: number;
  // refresh mode only: minimum settle duration. Quiet detection cannot succeed until at least this many ms have elapsed AND at least one byte of post-reset activity has been observed. Prevents false-quiet exits when onLensReset fires before the script's onAwake/onStart actually run.
  settleMinMs?: number;
  // refresh mode only: after settleMinMs has elapsed and activity has been seen, return once the log file has been quiet for this many consecutive ms. Set to 0 to skip settle entirely and return at the reset boundary (faster, but onAwake/onStart errors and prints will be missed).
  settleQuietMs?: number;
  // tail mode only: bytes to read from the end of the log file. Clamped to [1024, 262144]. Ignored in refresh mode.
  tailBytes?: number;
  // refresh mode only: max ms to wait for the Lens-reset signal after refreshing preview panels.
  timeoutMs?: number;
}): Promise<CallToolResult>; };
